#!/usr/bin/env node
/**
 * Conversion worker.
 *
 * The orchestrator dispatches this program once per layer by writing
 * state/dispatch.json:  { "layer": "<layerId>" }
 * (argv is honoured too when present, but the runner passes none.)
 *
 * It is the only component that touches src/. The orchestrator never writes
 * conversions itself.
 *
 * Responsibilities:
 *   - rewrite every file of the layer from .js -> .ts
 *   - add explicit `number` parameter and return types
 *   - repoint every relative import at the .ts file
 *   - delete the .js source
 *   - fail loudly (non-zero exit) if anything is left unconverted
 */
import { readFileSync, writeFileSync, unlinkSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const LAYERS = JSON.parse(readFileSync(join(ROOT, "job/layers.json"), "utf8")).layers;

// Dispatch: argv[2] wins, else the dispatch file the orchestrator wrote.
let layerId = process.argv[2];
if (!layerId) {
  const dispatchPath = join(ROOT, "state/dispatch.json");
  if (!existsSync(dispatchPath)) {
    console.error("no dispatch: write state/dispatch.json {\"layer\": \"<id>\"}");
    process.exit(2);
  }
  layerId = JSON.parse(readFileSync(dispatchPath, "utf8")).layer;
}
if (!layerId) {
  console.error("no layer id in dispatch");
  process.exit(2);
}
const layer = LAYERS.find((l) => l.id === layerId);
if (!layer) {
  console.error(`unknown layer: ${layerId}`);
  process.exit(2);
}

/** Rewrite one JS module body into typed TS. */
function convertSource(src) {
  let out = src;

  // 1. relative import specifiers: .js -> .ts
  out = out.replace(
    /(from\s*["'])([^"']+?)\.js(["'])/g,
    (_m, pre, path, post) => `${pre}${path}.ts${post}`,
  );

  // 2. explicit `number` parameter + return types on exported functions
  out = out.replace(
    /export\s+function\s+(\w+)\s*\(([^)]*)\)\s*(\{)/g,
    (_m, name, params, brace) => {
      const typed = params
        .split(",")
        .map((p) => p.trim())
        .filter(Boolean)
        .map((p) => `${p}: number`)
        .join(", ");
      return `export function ${name}(${typed}): number ${brace}`;
    },
  );

  return out;
}

const converted = [];

for (const rel of layer.files) {
  const jsPath = join(ROOT, rel);
  const tsPath = jsPath.replace(/\.js$/, ".ts");

  if (!existsSync(jsPath)) {
    // Already converted on a previous run (idempotent resume).
    if (existsSync(tsPath)) {
      console.log(`skip (already converted): ${rel}`);
      converted.push(tsPath);
      continue;
    }
    console.error(`missing source: ${rel}`);
    process.exit(1);
  }

  const original = readFileSync(jsPath, "utf8");
  const convertedSrc = convertSource(original);

  // --- verification gates before we touch the filesystem ---
  const fnCount = (original.match(/export\s+function/g) || []).length;
  const typedCount = (convertedSrc.match(/:\s*number/g) || []).length;
  if (fnCount === 0 || typedCount < fnCount) {
    console.error(`type annotation missing for ${rel}`);
    process.exit(1);
  }
  if (/\.js["']/.test(convertedSrc)) {
    console.error(`stale .js import left in ${rel}`);
    process.exit(1);
  }

  writeFileSync(tsPath, convertedSrc);
  unlinkSync(jsPath);
  console.log(`converted ${rel} -> ${tsPath}`);
  converted.push(tsPath);
}

// --- final gate: nothing of this layer may remain in .js form ---
for (const rel of layer.files) {
  if (existsSync(join(ROOT, rel))) {
    console.error(`js source still present: ${rel}`);
    process.exit(1);
  }
}

console.log(`layer ${layerId} converted: ${converted.length} file(s)`);

