import { existsSync, readdirSync, statSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..", "..");

function walk(dir, acc) {
  for (const e of readdirSync(dir)) {
    const p = join(dir, e);
    if (statSync(p).isDirectory()) walk(p, acc);
    else acc.push(p);
  }
  return acc;
}

const all = walk(root, []);

// 1. typed TS present, .js sources deleted in both leased trees
const mustExist = [
  "src/alpha/one.ts",
  "src/alpha/inc.ts",
  "src/beta/two.ts",
  "src/beta/dec.ts",
  "src/index.ts",
];
for (const rel of mustExist) {
  if (!existsSync(join(root, rel))) throw new Error("missing " + rel);
}
const mustNotExist = [
  "src/alpha/one.js",
  "src/alpha/inc.js",
  "src/beta/two.js",
  "src/beta/dec.js",
  "src/index.js",
];
for (const rel of mustNotExist) {
  if (existsSync(join(root, rel))) throw new Error("should be deleted: " + rel);
}

// 2. lease exclusivity: alpha files only under src/alpha, beta files only under src/beta
const alphaOwned = new Set(["one", "inc"]);
const betaOwned = new Set(["two", "dec"]);
for (const p of all) {
  const rel = p.slice(root.length + 1);
  if (rel.startsWith("src/beta/")) {
    const stem = rel.split("/").pop().replace(/\.ts$/, "");
    if (alphaOwned.has(stem)) throw new Error("cross-lease violation: alpha file in src/beta -> " + rel);
  }
  if (rel.startsWith("src/alpha/")) {
    const stem = rel.split("/").pop().replace(/\.ts$/, "");
    if (betaOwned.has(stem)) throw new Error("cross-lease violation: beta file in src/alpha -> " + rel);
  }
}

// 3. no CONFLICT / no src/shared at all
if (existsSync(join(root, "src", "shared"))) throw new Error("src/shared exists");
for (const p of all) {
  if (p.split("/").pop() === "CONFLICT") throw new Error("CONFLICT file present: " + p);
}

// 4. index.ts re-exports exactly the required names, with correct behavior
const mod = await import(join(root, "src", "index.ts"));
for (const name of ["one", "inc", "two", "dec"]) {
  if (typeof mod[name] !== "function") throw new Error("index.ts missing export: " + name);
}
if (mod.one(1) !== 2) throw new Error("one broken");
if (mod.inc(4) !== 5) throw new Error("inc broken");
if (mod.two(1) !== 3) throw new Error("two broken");
if (mod.dec(7) !== 6) throw new Error("dec broken");

// 5. no stray .js anywhere under src
for (const p of all) {
  const rel = p.slice(root.length + 1);
  if (rel.startsWith("src/") && rel.endsWith(".js")) throw new Error("stray .js under src: " + rel);
}

// 6. leases recorded
const leases = JSON.parse(await (await import("node:fs/promises")).readFile(join(root, "job", "leases.json"), "utf8"));
if (leases.leases.length !== 2) throw new Error("expected 2 leases");

console.log("ok");

